export interface KeyValueStorage {
  get(key: string): Promise<string | undefined>;
  set(key: string, value: string): Promise<void>;
  delete(key: string): Promise<void>;
  keys(): Promise<string[]>;
}

export interface SecretStoreOptions {
  storage: KeyValueStorage;
  masterPassword: string;
}

export interface SecretStore {
  put(owner: string, name: string, value: string): Promise<void>;
  get(owner: string, name: string): Promise<string | undefined>;
  list(owner: string): Promise<string[]>;
  remove(owner: string, name: string): Promise<boolean>;
}

export async function createSecretStore(
  options: SecretStoreOptions,
): Promise<SecretStore> {
  const { storage, masterPassword } = options;

  // Key for storing the PBKDF2 salt
  const SALT_KEY = "__secret_store__salt";
  // Prefix for secret keys
  const SECRET_PREFIX = "secret:";

  // Get or create salt
  let saltHex = await storage.get(SALT_KEY);
  if (!saltHex) {
    const salt = new Uint8Array(16);
    crypto.getRandomValues(salt);
    saltHex = bytesToHex(salt);
    await storage.set(SALT_KEY, saltHex);
  }

  const salt = hexToBytes(saltHex);

  // Derive AES-GCM key from master password using PBKDF2
  const baseKey = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(masterPassword),
    "PBKDF2",
    false,
    ["deriveKey"],
  );

  const aesKey = await crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );

  const encoder = new TextEncoder();
  const decoder = new TextDecoder();

  function makeKey(owner: string, name: string): string {
    return `${SECRET_PREFIX}${encodeURIComponent(owner)}:${encodeURIComponent(name)}`;
  }

  function makeListPrefix(owner: string): string {
    return `${SECRET_PREFIX}${encodeURIComponent(owner)}:`;
  }

  return {
    async put(owner: string, name: string, value: string): Promise<void> {
      const key = makeKey(owner, name);
      const aad = encoder.encode(owner + "\0" + name);
      const nonce = new Uint8Array(12);
      crypto.getRandomValues(nonce);

      const iv = new Uint8Array(12);
      crypto.getRandomValues(iv);

      const plaintext = encoder.encode(value);
      const ciphertext = await crypto.subtle.encrypt(
        { name: "AES-GCM", iv },
        aesKey,
        plaintext,
      );

      // Prepend nonce to ciphertext (ciphertext includes tag)
      const combined = new Uint8Array(12 + ciphertext.byteLength);
      combined.set(iv, 0);
      combined.set(new Uint8Array(ciphertext), 12);

      await storage.set(key, bytesToBase64(combined));
    },

    async get(owner: string, name: string): Promise<string | undefined> {
      const key = makeKey(owner, name);
      const stored = await storage.get(key);
      if (stored === undefined) return undefined;

      const data = base64ToBytes(stored);
      if (data.length < 12 + 16) {
        // Not enough data for nonce + tag minimum
        throw new Error("Corrupted secret data");
      }

      const iv = data.slice(0, 12);
      const ciphertext = data.slice(12);

      const aad = encoder.encode(owner + "\0" + name);

      try {
        const plaintext = await crypto.subtle.decrypt(
          { name: "AES-GCM", iv, additionalData: aad },
          aesKey,
          ciphertext,
        );
        return decoder.decode(plaintext);
      } catch (e) {
        throw new Error("Failed to decrypt secret: tampering detected");
      }
    },

    async list(owner: string): Promise<string[]> {
      const prefix = makeListPrefix(owner);
      const allKeys = await storage.keys();
      const names: string[] = [];

      for (const k of allKeys) {
        if (k.startsWith(prefix)) {
          const encodedName = k.slice(prefix.length);
          try {
            names.push(decodeURIComponent(encodedName));
          } catch {
            // Skip malformed keys
          }
        }
      }

      names.sort();
      return names;
    },

    async remove(owner: string, name: string): Promise<boolean> {
      const key = makeKey(owner, name);
      const stored = await storage.get(key);
      if (stored === undefined) return false;
      await storage.delete(key);
      return true;
    },
  };
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function base64ToBytes(b64: string): Uint8Array {
